// Check if the browser supports the getUserMedia API
const getUserMedia = (navigator.mediaDevices && navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices)) 
  || (navigator.webkitGetUserMedia && navigator.webkitGetUserMedia.bind(navigator))
  || (navigator.mozGetUserMedia && navigator.mozGetUserMedia.bind(navigator))
  || (navigator.msGetUserMedia && navigator.msGetUserMedia.bind(navigator));

if (!getUserMedia) {
  console.log("getUserMedia API not supported.");
  Script.Outputs.Failure();
  return;
}

// Create a new MediaRecorder instance
let mediaRecorder;
let chunks = [];

// Add promise variables here
let resolveDataAvailable;
let dataAvailablePromise = new Promise(resolve => {
  resolveDataAvailable = resolve;
});

// Start recording audio
Script.Signals.Start = async function () {
  try {
    const stream = await getUserMedia({ audio: true });
    mediaRecorder = new MediaRecorder(stream);
    console.log("Started recording...");

    // Create a new Promise for each recording
    dataAvailablePromise = new Promise(resolve => {
      resolveDataAvailable = resolve;
    });

    mediaRecorder.addEventListener('dataavailable', (event) => {
      chunks.push(event.data);
      console.log("Data available:", event.data); // Log the data chunks
      resolveDataAvailable(); // Resolve the promise
    });

    mediaRecorder.addEventListener('stop', () => {
      console.log("Stopped recording...");
    });

    mediaRecorder.start();
    Script.Outputs.AudioFile = "";
    Script.Outputs.Started();
  } catch (error) {
    console.log("Error:", error); // Log the error
    Script.Outputs.Error = error;
    Script.Outputs.Failure();
  }
};


// Stop recording audio
Script.Signals.Stop = async function() {
  if (mediaRecorder && mediaRecorder.state === 'recording') {
    mediaRecorder.stop();
    // Wait for the dataavailable event
    await dataAvailablePromise;
    const blob = new Blob(chunks, { type: 'audio/webm' });
    console.log("Audio blob:", blob); // Log the blob

    // Convert Blob to base64 string
    const reader = new FileReader();
    reader.readAsDataURL(blob);
    reader.onloadend = function() {
      const base64data = reader.result;
      Script.Outputs.AudioFile = base64data; // Output the base64 string
      Script.Outputs.Success();
    }

    chunks = []; // Clear the chunks array for future recordings
    // Reset for the next recording
    dataAvailablePromise = new Promise(resolve => {
      resolveDataAvailable = resolve;
    });
  }
};

Script.Outputs = {
    FileUrl: 'string',
    fileName: 'string',
    Success: 'signal',
    Error: 'string',
    Failure: 'signal'
};

// Function to convert base64 data to Blob
function base64ToBlob(base64, mimeType) {
    const byteCharacters = atob(base64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
        byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);

    // Create blob object
    const blob = new Blob([byteArray], {type: mimeType});
    return blob;
}

Script.Signals.UploadAudio = async function () {
    const audioDataUrl = Script.Inputs.AudioBlob;
    if (!audioDataUrl) return;

    const base64Data = audioDataUrl.split(',')[1];
    const blob = base64ToBlob(base64Data, 'audio/webm'); // Convert base64 to Blob
    const fileName = `audio_${Date.now()}.webm`;
    const file = new File([blob], fileName, { type: 'audio/webm' }); // Create File object

    try {
        const cloudFile = await Noodl.Files.upload(file, {
            onProgress: (p) => {
                console.log(p.total, p.loaded);
            },
        });

        Script.Outputs.file = cloudFile;
        Script.Outputs.FileUrl = cloudFile.url; // Assuming the URL is the file path
        Script.Outputs.fileName = cloudFile.name;
        Script.Outputs.Success();
    } catch (error) {
        Script.Outputs.Error = error;
        Script.Outputs.Failure();
    }
};

let timerId;
let seconds = 0;

Script.Signals.Start = async function () {
  if (timerId) {
    return;
  }

  seconds = 0; // Reset the seconds
  Script.Outputs.Seconds = "0:00";

  timerId = setInterval(() => {
    seconds++;
    let minutes = Math.floor(seconds / 60);
    let remainingSeconds = seconds % 60;
    let formattedSeconds = remainingSeconds < 10 ? '0' + remainingSeconds : remainingSeconds;
    Script.Outputs.Seconds = `${minutes}:${formattedSeconds}`;
  }, 1000);
}

Script.Signals.Stop = async function () {
  if (timerId) {
    clearInterval(timerId);
    timerId = null;
    let minutes = Math.floor(seconds / 60);
    let remainingSeconds = seconds % 60;
    let formattedSeconds = remainingSeconds < 10 ? '0' + remainingSeconds : remainingSeconds;
    Script.Outputs.Seconds = `${minutes}:${formattedSeconds}`;
  }
}
